(function(outputs, steps, params, stepResult, assertEqual) {
    describe('ATF-DT-01: Digital Twin Work Centers & IoT Telemetry', function() {
        var P = 'x_2056099_indust_0_';

        it('should have at least 12 digital twin work centers registered', function() {
            var gr = new GlideRecord(P + 'dt_work_center');
            gr.query();
            expect(gr.getRowCount()).toBeGreaterThanOrEqual(12);
        });

        it('should cover all 3 manufacturing facilities (Hyderabad, Chennai, Bengaluru)', function() {
            var plants = { 'Hyderabad': 0, 'Chennai': 0, 'Bengaluru': 0 };
            var gr = new GlideRecord(P + 'dt_work_center');
            gr.query();
            while (gr.next()) {
                var loc = gr.getValue('facility_location');
                if (loc in plants) plants[loc]++;
            }
            expect(plants['Hyderabad']).toBeGreaterThanOrEqual(3);
            expect(plants['Chennai']).toBeGreaterThanOrEqual(3);
            expect(plants['Bengaluru']).toBeGreaterThanOrEqual(3);
        });

        it('should have valid IoT telemetry parameters within physical tolerances', function() {
            var gr = new GlideRecord(P + 'dt_work_center');
            gr.query();
            while (gr.next()) {
                var temp = parseFloat(gr.getValue('operating_temp_c'));
                var vib = parseFloat(gr.getValue('vibration_mms'));
                var oee = parseFloat(gr.getValue('health_index_pct'));

                // Temp ranges from -45C (Cryo Testing) to 95C (CNC High Load)
                expect(temp).toBeGreaterThanOrEqual(-45.0);
                expect(temp).toBeLessThanOrEqual(95.0);

                // Vibration levels between 0.1 and 6.0 mm/s
                expect(vib).toBeGreaterThanOrEqual(0.1);
                expect(vib).toBeLessThanOrEqual(6.0);

                // OEE Health Index between 70% and 100%
                expect(oee).toBeGreaterThanOrEqual(70.0);
                expect(oee).toBeLessThanOrEqual(100.0);
            }
        });
    });
})(outputs, steps, params, stepResult, assertEqual);
